export interface AttachmentInfo {
    inline?: number;
    attachment: number;
}

export interface Attachment {
    ID?: string;
    Name?: string;
    Size?: number;
    Preview?: any;
    KeyPackets?: any;
    MIMEType?: string;
    data?: any;
    Headers?: { [key: string]: string };
    Encrypted?: number;
    Signature?: string;
    // EO specific
    DataPacket?: any;
}

export interface UnsubscribeMethods {
    Mailto?: {
        Subject?: string;
        Body?: string;
        ToList: string[];
    };
    HttpClient?: string;
    OneClick?: 'OneClick';
}

export interface MessageMetadata {
    ID: string;
    Order: number;
    DisplaySenderImage: number;
    ConversationID: string;
    Subject: string;
    Unread: number;
    /** @deprecated use Flags instead */
    Type?: number;
    /** @deprecated use Sender.Address instead */
    SenderAddress?: string;
    /** @deprecated use Sender.Name instead */
    SenderName?: string;
    Sender: Recipient;
    ToList: Recipient[];
    CCList: Recipient[];
    BCCList: Recipient[];
    Time: number;
    Size: number;
