    IsEncrypted?: number;
    ExpirationTime?: number;
    IsReplied: number;
    IsRepliedAll: number;
    IsForwarded: number;
    AddressID: string;
    LabelIDs: string[];
    ExternalID: string;
    NumAttachments: number;
    Flags: number;
    AttachmentInfo?: { [key in MIME_TYPES]?: AttachmentInfo };
}

