    Error?: string;
    Details?: string[];
}

export interface QueryMessageMetadataResponse {
    Code: number;
    Total: number;
    Messages: MessageMetadata[];
    TasksRunning: TaskRunning[];
}

export interface MarkAsBrokenResponse {
